using DotCharter.Services.Editing.FretAnchors;

namespace DotCharter.Tests.Core.Utilities;

/// <summary>
///     #502: <see cref="LearnedChordFingerings" /> — the shapes whose fingering the owner's finished charts settle
///     differently from the heuristic, generated by <c>tools/chart-eval --learn</c> from the TRAIN split. The
///     suggestion stays a pure function of the shape (transposed, the same entry applies), the table keeps its own
///     evidence thresholds, and the follower reads a learned fingering as the suggestion (FREE).
/// </summary>
public sealed class LearnedChordFingeringsTests
{
    private static ChordTemplate Shape(params (int String, int Fret)[] frets)
    {
        var t = new ChordTemplate();
        foreach (var (s, f) in frets) t.Frets[s] = f;
        return t;
    }

    private static string Fingers(ChordTemplate t) =>
        string.Join(" ", t.Frets.Keys.OrderBy(k => k).Select(k => t.Fingers.TryGetValue(k, out var f) ? f.ToString() : "-"));

    [Fact]
    public void TheKey_IsTheShapeMovedDownToItsLowestFret()
    {
        Assert.Equal("6|0,x,o,0,1,x", LearnedChordFingerings.KeyOf(Shape((0, 5), (2, 0), (3, 5), (4, 6)), 6));
        Assert.Equal("6|0,x,o,0,1,x", LearnedChordFingerings.KeyOf(Shape((0, 3), (2, 0), (3, 3), (4, 4)), 6));
        Assert.Null(LearnedChordFingerings.KeyOf(Shape((0, 0), (1, 0)), 6));
    }

    [Theory]
    [InlineData(5)]
    [InlineData(3)]
    [InlineData(8)]
    public void TheThumbOverShape_TakesTheChartersFingering_AnywhereOnTheNeck(int root)
    {
        // Low-E root, A muted, D open, then the root's octave and a third on G/B: thumb over the neck, index and
        // ring — 177 of the 219 train chords of this shape, in 5 songs. The heuristic says 1-2-3.
        var shape = Shape((0, root), (2, 0), (3, root), (4, root + 1));
        var heuristic = Shape((0, root), (2, 0), (3, root), (4, root + 1));

        ChordTemplateFingerSetter.SetSuggestedFingers(shape, 6);
        ChordTemplateFingerSetter.SetHeuristicFingers(heuristic, 6);

        Assert.Equal("0 - 1 3", Fingers(shape));
        Assert.Equal("1 - 2 3", Fingers(heuristic));
    }

    [Fact]
    public void EveryLearnedShape_IsWhatTheSuggesterGives_AndKeepsTheGeneratorsEvidenceBar()
    {
        Assert.NotEmpty(LearnedChordFingerings.All);
        foreach (var learned in LearnedChordFingerings.All)
        {
            // The thresholds tools/chart-eval --learn applies (LearnMode.MinShare / MinSongs): a hand-edited entry
            // without the evidence fails here.
            Assert.True(learned.Chords >= 0.75 * learned.OfChords, $"{learned.Key}: {learned.Chords} of {learned.OfChords}");
            Assert.True(learned.Songs >= 3, $"{learned.Key}: {learned.Songs} songs");

            var template = FromKey(learned.Key, lowest: 5);
            ChordTemplateFingerSetter.SetSuggestedFingers(template, 6);
            foreach (var (s, fret) in template.Frets)
            {
                if (fret == 0) Assert.False(template.Fingers.ContainsKey(s), learned.Key);
                else Assert.Equal(learned.Fingers[s], template.Fingers[s]);
            }
        }
    }

    [Fact]
    public void ALearnedFingering_IsFreeForTheFollower()
    {
        // The walk may hold the hand for a FREE chord and the follower re-fingers it; "free" means "what the
        // suggester gives", so a learned fingering must read as free, the heuristic's as authored.
        var learned = Shape((0, 5), (2, 0), (3, 5), (4, 6));
        ChordTemplateFingerSetter.SetSuggestedFingers(learned, 6);
        var heuristic = Shape((0, 5), (2, 0), (3, 5), (4, 6));
        ChordTemplateFingerSetter.SetHeuristicFingers(heuristic, 6);

        Assert.True(ChordFingeringFollower.IsFreeFingering(learned, 6));
        Assert.False(ChordFingeringFollower.IsFreeFingering(heuristic, 6));
    }

    private static ChordTemplate FromKey(string key, int lowest)
    {
        var t = new ChordTemplate();
        var tokens = key[(key.IndexOf('|') + 1)..].Split(',');
        for (var s = 0; s < tokens.Length; s++)
        {
            if (tokens[s] == "x") continue;
            t.Frets[s] = tokens[s] == "o" ? 0 : lowest + int.Parse(tokens[s]);
        }

        return t;
    }
}
